prompts=[]
for sheet in range(6):
 group=people[sheet*5:(sheet+1)*5]
 prompt='Use case: illustration-story. Production transparent NPC atlas for the existing warm hand-painted Sintra 2D RPG. Input is STYLE ONLY, do not duplicate its identities. Exactly FIVE equal columns and FOUR rows, twenty complete separate full-body sprites. Generous clear gutters and bottom margin.\n'
 for col,p in enumerate(group):prompt+=f'Column {col+1}: {p["name"]}, {p["appearance"]}. Characteristic activity: {p["purpose"]}.\n'
 prompt+='Rows 1 and 2: two visibly different authored activity gestures appropriate to each individual, all props held close to body. Rows 3 and 4: the SAME five individuals walking to the RIGHT, two alternating arm/leg strides, carrying their own small props. Keep identical faces, hair, clothing, proportions and props in each column across all four rows. Friendly natural anatomy, textured gouache and pencil, warm subtle contours, neutral daylight exactly like the supplied style. Each complete person, shoes and hand props fit entirely inside cell; keep figures small enough for all four rows, especially bottom feet. No floor, scenery, text, logos, numbers, borders, watermark, extra people or background. TRUE alpha transparency, portrait composition.'
 prompts.append(dict(file=f'living-people-{sheet+1:02d}.png',prompt=prompt))
prompts.append(dict(file='living-animals.png',prompt='Use case: illustration-story. Transparent production sprite atlas matching the warm textured hand-painted Sintra RPG style reference. A clean FOUR COLUMN by TWO ROW grid, eight COMPLETE isolated sprites. Top row: the SAME plump gray pigeon with iridescent green neck, coral feet: walking right, pecking right, wings wide flying right, landing wings half open. Bottom row: the SAME ginger and white Portuguese alley cat with green eyes: sleeping curled, sitting washing paw, walking right left legs forward, walking right opposite stride. Natural proportions, friendly believable animals, gouache pencil textured subtle outlines. Each full body all wings and tails safely inside its cell with generous transparent margins, no cropping, ground, scenery, text, letters or watermark. True alpha transparency, landscape sheet.'))
prompts.append(dict(file='living-objects.png',prompt='Use case: illustration-story. Production object atlas for a Portuguese hand-painted 2D RPG matching supplied warm gouache and pencil style. Transparent FOUR columns by TWO rows, EIGHT separate complete objects each entirely within its cell, generous margins. Top row from left: a small brass outdoor house doorbell with porcelain button; an open blue Portuguese community lost-and-found wooden chest with a brass lock; a paper notice board on two short wooden legs with pinned tiny papers WITHOUT legible text; a small public drinking fountain with blue-and-white ceramic tile front and brass tap. Bottom row: a traditional green street litter bin; a striped vintage coin vending machine selling postcards; a flowerpot of lush red geraniums with copper watering can beside it; a wooden barter stand with bent spoons, bottle caps and old postcards. Natural oblique front/side RPG perspective, warm subtle contours, rich native painted detail. No floor, background, lettering, watermark, grid lines, cropping or overlaps. TRUE alpha transparency.'))
(R/'data/village/living-image-prompts.json').write_text(json.dumps(prompts,ensure_ascii=False,indent=2)+'\n')
